// Anti-jitter for amplified head tracking (added feature, v41).
//
// Background. The comfort-range calibration (v35) multiplies the cursor's
// sensitivity per direction, up to ×12, so that a small comfortable head
// motion still reaches the screen corner. That multiplier does not know the
// difference between "the user turned their head" and "the camera's point
// tracking wobbled by a pixel" - it amplifies both. The point tracker's
// residual tremor is a couple of pixels' worth of cursor motion per frame at
// gain 1, which is invisible; at ×12 it is a visible shake. Because the
// vertical direction has much less travel to play with (and because the
// up/down gains can come out wildly different from each other, since a corner
// step measures both axes at once), the shake shows up as the cursor running
// up and down - and the calibration's verification button, which is 110px
// tall, becomes impossible to hit.
//
// Three layers, all pure and unit tested:
//
//  1. `balanceGains` - cap the gain (×12 → ×6) and stop one direction of a
//     pair from being much stronger than its opposite. Up and down (left and
//     right) are physically almost identical ranges; a 9x difference is a
//     measurement artifact, not a neck. An asymmetric pair also *rectifies*
//     tremor: the same wobble pushes hard one way and weakly the other, so
//     the cursor drifts instead of just trembling.
//  2. `jitterProfile` - the two knobs derived from the gain that is actually
//     applied: a deadband (in output pixels) that grows with the
//     amplification, and a smoothing factor that grows with it too. At gain 1
//     both are neutral, so uncalibrated users keep the exact response they
//     had before (this module is a no-op for them).
//  3. `applyJitterFilter` - the per-frame filter: drop sub-deadband frames
//     (noise), then smooth what is left (tremor is zero-mean, so averaging
//     neighbouring frames cancels it while a sustained motion passes
//     through).

export const GAIN_BALANCE_MAX_RATIO = 2; // up/down (left/right) may differ by at most this
export const COMFORT_GAIN_CEILING = 6; // highest gain actually applied (was 12)
export const GAIN_FLOOR = 0.5;
// Deadband in output pixels, gained per unit of amplification. Kept small:
// at gain 6 it is ~3.6px/frame (~110px/s), i.e. only head movements the user
// cannot be making - a normal move is 10px+/frame, and a bigger deadband
// would make ordinary steering stutter.
export const JITTER_DEADBAND_PX = 0.6;

// How hard to smooth. 0 = off (raw deltas), higher = smoother but laggier.
// Only scales with (gain - 1), so it stays a no-op without calibration.
export const JITTER_SMOOTHING = { off: 0, normal: 0.35, strong: 0.65 };

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));

export function clampGain(gain, { min = GAIN_FLOOR, max = COMFORT_GAIN_CEILING } = {}) {
	if (!isFinite(gain) || gain <= 0) {
		return 1;
	}
	return clamp(gain, min, max);
}

/**
 * Bring a pair of opposite-direction gains closer together, keeping their
 * geometric mean. Only touches pairs that differ by more than `maxRatio`, so
 * a genuine (small) left/right asymmetry the user needs survives.
 * @returns {[number, number]} the adjusted pair, in the same order
 */
export function balancePair(a, b, maxRatio = GAIN_BALANCE_MAX_RATIO) {
	if (!isFinite(a) || !isFinite(b) || a <= 0 || b <= 0) {
		return [a, b];
	}
	const hi = Math.max(a, b);
	const lo = Math.min(a, b);
	if (hi / lo <= maxRatio) {
		return [a, b];
	}
	const mid = Math.sqrt(hi * lo);
	const spread = Math.sqrt(maxRatio);
	const newHi = Math.min(hi, mid * spread);
	const newLo = Math.max(lo, mid / spread);
	return a >= b ? [newHi, newLo] : [newLo, newHi];
}

/**
 * Clamp + balance the four per-direction gains the way they are about to be
 * applied. Safe to call every frame: with in-range, symmetric gains it returns
 * the same numbers (so a freshly calibrated result is a no-op).
 */
export function balanceGains(
	{ left = 1, right = 1, up = 1, down = 1 },
	{ maxRatio = GAIN_BALANCE_MAX_RATIO, max = COMFORT_GAIN_CEILING } = {},
) {
	const [newLeft, newRight] = balancePair(clampGain(left, { max }), clampGain(right, { max }), maxRatio);
	const [newUp, newDown] = balancePair(clampGain(up, { max }), clampGain(down, { max }), maxRatio);
	return { left: newLeft, right: newRight, up: newUp, down: newDown };
}

/**
 * The deadband and smoothing factor for one axis, given the gain that will be
 * applied to it. Both are 0 / 1 (i.e. "do nothing") at gain 1.
 */
export function jitterProfile(gain, level = "normal") {
	const strength = JITTER_SMOOTHING[level] ?? JITTER_SMOOTHING.normal;
	const excess = Math.max(0, clampGain(gain) - 1);
	// "off" is a genuine escape hatch: no deadband, no smoothing, exactly the
	// raw movement (the cap and the balancing still apply - those are what stop
	// the cursor from drifting to one side).
	return {
		deadbandPx: strength === 0 ? 0 : JITTER_DEADBAND_PX * excess,
		// alpha 1 = pass through unchanged; smaller = smoother.
		alpha: 1 / (1 + strength * excess),
	};
}

export function createJitterFilterState() {
	return { x: 0, y: 0 };
}

export function resetJitterFilter(state) {
	state.x = 0;
	state.y = 0;
	return state;
}

// One axis: exponential smoothing first, then a hard deadband on the OUTPUT.
// The order matters - gating the input and resetting the smoother there would
// rectifying the tremor (every sign change restarts the average from zero, so
// the rising half of a wobble leaks through while the falling half doesn't),
// which is exactly the "cursor slowly creeps to one side" failure this module
// is meant to remove. The smoother keeps tracking the real input either way,
// so it also can't leave a stale value behind to drag the cursor later.
function filterAxis(previous, delta, { deadbandPx, alpha }, extent) {
	const next = alpha < 1 ? previous + (delta - previous) * alpha : delta;
	if (deadbandPx > 0 && Math.abs(delta * extent) < deadbandPx) {
		return { previous: next, delta: 0 };
	}
	return { previous: next, delta: next };
}

/**
 * One frame of the anti-jitter filter.
 * @param state {{x: number, y: number}} mutable, from createJitterFilterState()
 * @param p {{
 *   deltaX, deltaY, // this frame's head-driven cursor movement (fractions of
 *                   // the screen, after gain and after the max-speed cap)
 *   gainX, gainY, // the per-direction gains that were applied
 *   level, // "off" | "normal" | "strong"
 *   screenWidth, screenHeight,
 * }}
 * @returns {{deltaX, deltaY, deadbandX, deadbandY}} the movement to apply
 */
export function applyJitterFilter(state, {
	deltaX = 0,
	deltaY = 0,
	gainX = 1,
	gainY = 1,
	level = "normal",
	screenWidth = 1,
	screenHeight = 1,
} = {}) {
	const profileX = jitterProfile(gainX, level);
	const profileY = jitterProfile(gainY, level);
	const x = filterAxis(state.x, deltaX, profileX, screenWidth);
	const y = filterAxis(state.y, deltaY, profileY, screenHeight);
	state.x = x.previous;
	state.y = y.previous;
	return { deltaX: x.delta, deltaY: y.delta, deadbandX: profileX.deadbandPx, deadbandY: profileY.deadbandPx };
}
